    // Builds an encryptable message for the given nonce, adding each entry of params as a field.
    QJsonObject buildMessageWithParams(const QString& nonce, const QVariantMap& params)
    {
        auto message = browserMessageBuilder()->buildMessage(nonce);
        for (auto i = params.constBegin(); i != params.constEnd(); ++i) {
            message[i.key()] = QJsonValue::fromVariant(i.value());
        }
        return message;
    }
} // namespace

